import { findById } from './users.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

/** Valid status transitions: open -> in_progress -> done */
const VALID_TRANSITIONS: Record<Task['status'], Task['status'] | null> = {
  open: 'in_progress',
  in_progress: 'done',
  done: null,
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache: Cache;

  constructor() {
    this.cache = new Cache();
  }

  private invalidateCache(id: string): void {
    this.cache.invalidate(id);
  }

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    // Validate the creator and assignee exist
    findById(input.createdBy);
    findById(input.assignee);

    // Validate title is not empty
    if (!input.title.trim()) {
      throw new Error('Task title cannot be empty');
    }

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);

    // Audit log
    record({ action: 'create', userId: input.createdBy, taskId: task.id, timestamp: Date.now() });

    return task;
  }

  getTask(id: string): Task | null {
    // Try cache first
    const cached = this.cache.get<Task>(id);
    if (cached !== null) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (allowed !== status) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${status}`
      );
    }

    task.status = status;
    this.invalidateCache(id);

    // Audit log
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: status,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    this.tasks.delete(id);
    this.invalidateCache(id);

    // Audit log
    record({ action: 'delete', userId, taskId: id, timestamp: Date.now() });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

