import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function csvEscape(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n') ||
    value.includes('\r')
  ) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error(`User ${userId} does not have export permission`);
  }

  const tasks = Array.from(
    (taskManager as { tasks: Map<string, import('./tasks.js').Task> }).tasks.values()
  );

